import React, { useState } from 'react';
import { useClipboard } from '../contexts/ClipboardContext';
import { useAuth } from '../contexts/AuthContext';
import { Navigate } from 'react-router-dom';
import { TrashIcon, SparklesIcon } from '@heroicons/react/24/outline';

const Admin = () => {
  const { clipboards, deleteClipboard, loading, error } = useClipboard();
  const { user } = useAuth();
  const [selectedClipboards, setSelectedClipboards] = useState(new Set());
  const [deleteStatus, setDeleteStatus] = useState('');

  if (!user?.isAdmin) {
    return <Navigate to="/dashboard" />;
  }

  const handleSelectAll = (e) => {
    if (e.target.checked) {
      setSelectedClipboards(new Set(clipboards.map(clip => clip._id)));
    } else {
      setSelectedClipboards(new Set());
    }
  };

  const handleSelect = (id) => {
    const newSelected = new Set(selectedClipboards);
    if (newSelected.has(id)) {
      newSelected.delete(id);
    } else {
      newSelected.add(id);
    }
    setSelectedClipboards(newSelected);
  };

  const handleDeleteSelected = async () => {
    if (!window.confirm('✨ Are you sure you want to delete the selected magic? ✨')) {
      return;
    }

    setDeleteStatus('🌟 Casting delete spell...');
    try {
      const promises = Array.from(selectedClipboards).map(id => deleteClipboard(id));
      await Promise.all(promises);
      setSelectedClipboards(new Set());
      setDeleteStatus('✨ Magic successfully vanished!');
    } catch (err) {
      console.error('Error deleting clipboards:', err);
      setDeleteStatus('💔 The spell failed to delete some magic');
    }
  };

  const handleDeleteSingle = async (id) => {
    if (!window.confirm('Are you sure you want to delete this clipboard?')) {
      return;
    }

    try {
      await deleteClipboard(id);
      setDeleteStatus('Successfully deleted clipboard');
    } catch (err) {
      setDeleteStatus('Failed to delete clipboard');
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[60vh]">
        <div className="animate-spin-slow text-fun-purple">
          <SparklesIcon className="h-16 w-16" />
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
      <div className="flex flex-col sm:flex-row justify-between items-center mb-8">
        <h1 className="fun-title text-3xl mb-4 sm:mb-0">
          ✨ Magic Control Center
        </h1>
        {selectedClipboards.size > 0 && (
          <button
            onClick={handleDeleteSelected}
            className="fun-button !bg-gradient-sunset group animate-pulse-fast"
          >
            <TrashIcon className="h-5 w-5 mr-2 inline group-hover:animate-wiggle" />
            Vanish Selected Magic ({selectedClipboards.size})
          </button>
        )}
      </div>

      {error && (
        <div className="fun-card border-fun-red bg-red-50/50 dark:bg-red-900/50 text-red-600 dark:text-red-200 p-4 mb-6 animate-bounce-slow" role="alert">
          <span className="block sm:inline">🔮 Oops! {error}</span>
        </div>
      )}

      {deleteStatus && (
        <div className="fun-card border-fun-purple bg-purple-50/50 dark:bg-purple-900/50 text-purple-600 dark:text-purple-200 p-4 mb-6 animate-float" role="alert">
          <span className="block sm:inline">{deleteStatus}</span>
        </div>
      )}

      <div className="fun-card divide-y divide-fun-purple/20">
        <div className="p-4 flex items-center">
          <label className="fun-button !bg-gradient-party inline-flex items-center cursor-pointer">
            <input
              type="checkbox"
              className="form-checkbox h-4 w-4 text-fun-purple rounded border-fun-purple/30 focus:ring-fun-purple/50"
              onChange={handleSelectAll}
              checked={selectedClipboards.size === clipboards.length}
            />
            <span className="ml-2">Select All Magic</span>
          </label>
        </div>

        <div className="divide-y divide-fun-purple/20">
          {clipboards.map((clipboard) => (
            <div key={clipboard._id} className="p-6 hover:bg-white/50 dark:hover:bg-dark-card/50 transition-all duration-300">
              <div className="flex items-start justify-between">
                <div className="flex items-center">
                  <input
                    type="checkbox"
                    className="form-checkbox h-4 w-4 text-fun-purple rounded border-fun-purple/30 focus:ring-fun-purple/50"
                    checked={selectedClipboards.has(clipboard._id)}
                    onChange={() => handleSelect(clipboard._id)}
                  />
                  <div className="ml-4">
                    <h3 className="fun-title text-xl">{clipboard.title}</h3>
                    <p className="mt-1 text-gray-600 dark:text-gray-300 break-words">{clipboard.content}</p>
                    <div className="mt-2 flex items-center text-sm space-x-4">
                      <span className={`fun-button !py-1 !px-2 ${
                        clipboard.isPrivate 
                          ? '!bg-gradient-sunset' 
                          : '!bg-gradient-party'
                      }`}>
                        {clipboard.isPrivate ? '🔒 Secret Magic' : '🌎 Public Magic'}
                      </span>
                      <span className="text-fun-purple">
                        ✨ Created: {new Date(clipboard.createdAt).toLocaleString()}
                      </span>
                    </div>
                  </div>
                </div>
                <button
                  onClick={() => handleDeleteSingle(clipboard._id)}
                  className="fun-button !bg-gradient-sunset ml-4 group"
                >
                  <TrashIcon className="h-5 w-5 group-hover:animate-wiggle" />
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

export default Admin;
